window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"CCxbQdjb_A8","speaker":"James Marape","role":"Prime Minister","country":"Papua New Guinea","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=CCxbQdjb_A8","date":"20260925","title":"🇵🇬 Papua New Guinea - Prime Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1389,"words":3273,"counts":{"claims":35,"promises":2,"attacks":0},"topics":[{"topic":"Religious freedom","share":0.2279,"seconds":316},{"topic":"Climate change","share":0.1373,"seconds":191},{"topic":"UNGA ceremony","share":0.0793,"seconds":110},{"topic":"Papua New Guinea human rights","share":0.0506,"seconds":70},{"topic":"Global interdependence","share":0.05,"seconds":69},{"topic":"Papua New Guinea constitution","share":0.049,"seconds":68},{"topic":"Human rights","share":0.0486,"seconds":68},{"topic":"Papua New Guinea","share":0.0465,"seconds":65},{"topic":"UN Secretary General","share":0.0461,"seconds":64},{"topic":"Papua New Guinea diversity","share":0.0449,"seconds":62},{"topic":"Papua New Guinea environment","share":0.0448,"seconds":62},{"topic":"UN multilateralism","share":0.0439,"seconds":61},{"topic":"Christian nations","share":0.0438,"seconds":61},{"topic":"Papua New Guinea development","share":0.0437,"seconds":61},{"topic":"Pacific nation","share":0.0437,"seconds":61}],"timeline":[[4,68,"Papua New Guinea"],[70,131,"UN multilateralism"],[132,202,"UNGA ceremony"],[203,267,"UN Secretary General"],[268,335,"Human rights"],[336,403,"Religious freedom"],[404,472,"Papua New Guinea constitution"],[473,536,"Religious freedom"],[537,597,"Religious freedom"],[598,661,"Papua New Guinea diversity"],[662,726,"Religious freedom"],[727,793,"Climate change"],[794,855,"Climate change"],[856,919,"Papua New Guinea environment"],[920,989,"Global interdependence"],[990,1053,"Climate change"],[1054,1115,"Pacific nation"],[1116,1177,"Christian nations"],[1178,1240,"Religious freedom"],[1241,1301,"Papua New Guinea development"],[1302,1372,"Papua New Guinea human rights"],[1374,1414,"UNGA ceremony"]],"stances":{"Papua New Guinea":"James Marape expresses greetings from Papua New Guinea and states the nation's profound respect for the UN Charter.","UN multilateralism":"James Marape asserts that all nations, regardless of size or power, must work together within the UN framework to address global challenges.","UNGA ceremony":"James Marape expresses gratitude to the UN for providing a platform for small nations and acknowledges the contributions of Pacific leaders and the Secretary-General.","UN Secretary General":"James Marape expresses deep gratitude and high praise for the UN Secretary General's service, advocacy for small nations, and personal engagement with Papua New Guinea.","Human rights":"James Marape asserts that human rights are God-given inherent dignities that must be respected and protected by all nations regardless of differences.","Religious freedom":"James Marape argues that religious majority power must not suppress minorities and that mutual respect is essential despite differing beliefs.","Papua New Guinea constitution":"James Marape asserts that the PNG Constitution guarantees freedom of conscience and religion, and that faith cannot be forced.","Papua New Guinea diversity":"James Marape argues that Papua New Guinea's experience proves that cultural and linguistic diversity does not necessitate national division.","Climate change":"James Marape argues that respecting human dignity requires protecting the environment and ensuring basic resources like water, as all nations share a single planet.","Papua New Guinea environment":"James Marape asserts that Papua New Guinea acts as a custodian of its natural resources and emphasizes the responsibility to protect the environment for future generations.","Global interdependence":"James Marape argues that powerful nations have a responsibility to consider the impact of their economic and military decisions on ordinary people in developing countries.","Pacific nation":"James Marape argues that a nation's power, regardless of size or economic status, does not diminish the rights and dignity of others and must be exercised with responsibility.","Christian nations":"James Marape asserts that Christian nations must prioritize peace over war and defines promoting peace as a requirement for being considered sons of God.","Papua New Guinea development":"James Marape outlines Papua New Guinea's progress in economic growth, infrastructure, education, health, green energy, and judicial independence while thanking the UN for its support over 51 years.","Papua New Guinea human rights":"James Marape states that his government is working to protect the human rights of all citizens and calls for global respect for human rights."},"claims":[{"t":44,"quote":"a nation of extraordinary diversity with more than 800 languages and cultures, but united under one flag","topic":"Papua New Guinea","kind":"fact"},{"t":70,"quote":"The United Nations reminds us that whether we are big or small rich or poor nations, developed or powerful or less powerful, we are all members of one international community.","topic":"UN multilateralism","kind":"fact"},{"t":99,"quote":"No nation can address them alone.","topic":"UN multilateralism","kind":"fact"},{"t":164,"quote":"I also wish to acknowledge the secretary general of United Nations, his excellency Antonio Guares as he approaches the completion of his tener.","topic":"UNGA ceremony","kind":"fact"},{"t":228,"quote":"Secretary General on behalf of my 11 million people, Papa Nigini, thank you for your service to the United Nations and to humanity.","topic":"UN Secretary General","kind":"fact"},{"t":239,"quote":"We remember fondly your three nights. You stayed with us in the mountains and islands of Papa Nigini.","topic":"UN Secretary General","kind":"fact"},{"t":286,"quote":"Every human being has inherent dignity and is entitled to fundamental freedoms.","topic":"Human rights","kind":"fact"},{"t":292,"quote":"From a Christian perspective, these freedoms are not gifts bestowed upon humanity by governments or institutions or powerful nations. They are God-given rights inherent in every human life.","topic":"Human rights","kind":"fact"},{"t":397,"quote":"Papa New Guinea, for instance, is a Christian nation believing that Jesus Christ is our Lord, Savior, and sooncoming King.","topic":"Religious freedom","kind":"fact"},{"t":422,"quote":"the fathers of my country's constitution in 1975 in fact uh right from the foundation of our constitution section 45 of our constitution guarantees every person freedom of conscience thought and religion","topic":"Papua New Guinea constitution","kind":"fact"},{"t":448,"quote":"Our constitution also protects people against being compelled to part participate in religious observance and against attempts to force religion or irreligion upon another person.","topic":"Papua New Guinea constitution","kind":"fact"},{"t":504,"quote":"So the universal declaration of human right recognizes this principle in article 18, the right to freedom of thought, conscience and religion.","topic":"Religious freedom","kind":"fact"},{"t":524,"quote":"Human beings have been persecuted, expelled, imprisoned, killed because of the fate.","topic":"Religious freedom","kind":"fact"},{"t":563,"quote":"The United States, for instance, this country where we where we stand on where the assembly meets, expressed a principle more than two centuries ago to its first amendment which prohibits laws respecting the an establishment of religion or prohibiting the free exercise thereof.","topic":"Religious freedom","kind":"fact"},{"t":588,"quote":"Papa New Guinea supports this principle. We are proudly Christian.","topic":"Religious freedom","kind":"self_credit"},{"t":624,"quote":"We have more than 800 languages and many different cultures and tradition.","topic":"Papua New Guinea diversity","kind":"number"},{"t":629,"quote":"Yet for 51 years as an independent nation, we have remained together as one papu nigini.","topic":"Papua New Guinea diversity","kind":"fact"},{"t":682,"quote":"Look within your borders. Ensure that religious minorities are not persecuted, suppressed, intimidated or discriminated because they practice a religion that is different from majority.","topic":"Religious freedom","kind":"fact"},{"t":702,"quote":"The fate of the majority must never become an instrument for the persecution of minority.","topic":"Religious freedom","kind":"fact"},{"t":752,"quote":"The United Nations General Assembly has recognized the human right to a clean, healthy, sustainable environment.","topic":"Climate change","kind":"fact"},{"t":794,"quote":"There is no other known habitable planet presently within reach of humanity.","topic":"Climate change","kind":"fact"},{"t":809,"quote":"Billions and billions of light years into the observable universe you find no planet like our planet earth.","topic":"Climate change","kind":"fact"},{"t":891,"quote":"We are custodians of great tropical forests, extraordinary biodiversity and vast ocean space.","topic":"Papua New Guinea environment","kind":"fact"},{"t":928,"quote":"Wars can disrupt food, fuel, energy, trade, supply chains far from the battlefield.","topic":"Global interdependence","kind":"fact"},{"t":934,"quote":"Economic decisions made in the world's largest economy can reach an ordinary family in a small developing country.","topic":"Global interdependence","kind":"fact"},{"t":990,"quote":"When climate changes, communities that have contributed little to global greenhouse gas emissions can nevertheless face rising seas, extreme weather, threats to food security, and damage to life livelihoods.","topic":"Climate change","kind":"fact"},{"t":1067,"quote":"Just few years ago, we became a middle- inome earning nation.","topic":"Pacific nation","kind":"fact"},{"t":1165,"quote":"Our Lord and Savior Jesus talks about peace and not war.","topic":"Christian nations","kind":"fact"},{"t":1169,"quote":"Those who are pro promoting peace are sons of God.","topic":"Christian nations","kind":"fact"},{"t":1214,"quote":"Papa Nigini will remain proudly proudly Christian. But we will also remain committed to the freedom of conscience, thought and religion.","topic":"Religious freedom","kind":"fact"},{"t":1270,"quote":"those who have stood in Papa Nigini the last 51 years of our nationhood","topic":"Papua New Guinea development","kind":"fact"},{"t":1278,"quote":"we are growing economy","topic":"Papua New Guinea development","kind":"fact"},{"t":1284,"quote":"We're making to making to make sure quality education and health services covers all people","topic":"Papua New Guinea development","kind":"fact"},{"t":1325,"quote":"my government is working to the best of ability to protect the rights of the 11 million people of my country","topic":"Papua New Guinea human rights","kind":"fact"},{"t":1390,"quote":"Until Jesus come, we must work to protect our planet.","topic":"UNGA ceremony","kind":"fact"}],"promises":[{"t":1209,"quote":"We must leave our children a better world than the one we are presently living in.","topic":"Religious freedom","kind":"promise"},{"t":1238,"quote":"Let us use it wisely and pass it to the next generation.","topic":"Religious freedom","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":4,"topic":"Papua New Guinea","text":"The assembly will now hear an address by his excellency James Marappe, Prime Minister of the Independence State of Papua Nuigina. I request protocol to escort his excellency and invite him to address the assembly. Mr. President, Secretary General, excellencies, [snorts] distinguished delegates, I bring to you greetings from Papa Nigini, a nation of extraordinary diversity with more than 800 languages and cultures, but united under one flag. Mr. President Papini comes to this assembly with profound respect for the charter of the United Nations and for the principles and purposes upon which this great institution was founded."},{"t":70,"topic":"UN multilateralism","text":"The United Nations reminds us that whether we are big or small rich or poor nations, developed or powerful or less powerful, we are all members of one international community. The challenges confronting humanity do not recognize the size of our economies, the strength of our militaries, [snorts] or the boundaries on our map. No nation can address them alone. We must therefore continue to work together respecting the sovereignty of all nations, upholding the international law and the United Nations charter, resolving our differences peacefully, and recognizing that every nation, regardless of its size or economic strength or military might, has a voice and a place in this assembly. for Papa Nigini and all the nations of the Pacific multilateralism methods."},{"t":132,"topic":"UNGA ceremony","text":"The United Nations place [snorts] provides a place rather where small nations can sit alongside the largest, where a voice can be heard and where we can work together on the common challenges facing humanity. And with this I want to place on record Papa Nigini's fullest acknowledgement on all speakers from the Pacific who have spoken all leaders who spoke. We I fully on behalf of Papa Nigini affirm all their points the points that was raised. I also wish to acknowledge the secretary general of United Nations, his excellency Antonio Guares as he approaches the completion of his tener. On behalf of the government and people of Papu Nigini, I want to thank the secretary general for his strong and consistent advocacy for humanity at a time when our world has confronted war, displacement, poverty, inequality, climate change, and many other challenges. He has consistently called for peace, human dignity, international cooperation and respect for the principles of United Nations."},{"t":203,"topic":"UN Secretary General","text":"He has demonstrated the qualities of a global statement. If there is anyone befitting of a global peace award and labeled a global statement uh his excellency is perhaps the leading person at this at his time. He has used his office to speak for humanity, including those voices that are often too dim and seemingly unheard. Secretary General on behalf of my 11 million people, Papa Nigini, thank you for your service to the United Nations and to humanity. We remember fondly your three nights. You stayed with us in the mountains and islands of Papa Nigini. Thank you for being a strong voice of not just Papa Nigini but small nations especially my small Pacific island nations. Your advocacy reminds us that beyond our national borders and political differences, cultures and beliefs, we belong to one human family and we serve one planet called the planet earth."},{"t":268,"topic":"Human rights","text":"Mr. President, it is in the spirit of common humanity that I wish to speak about human rights, human freedoms and particularly freedom of conscience, thought, belief and religion. At the heart of human rights is a simple truth. Every human being has inherent dignity and is entitled to fundamental freedoms. From a Christian perspective, these freedoms are not gifts bestowed upon humanity by governments or institutions or powerful nations. They are God-given rights inherent in every human life. And because this right belongs equally to every person, we have a responsibility to respect and protect the rights of others, including those who may not look like us or speak like us or worship like us or believe what we believe. The strength of a nation, a government, or an economy or a technology or a religion should never be used to suppress the fundamental human rights of another human being."},{"t":336,"topic":"Religious freedom","text":"The might of military power must not suppress the weak. The might of economic power must not suppress the poor. The might of technology must not be used to diminish human dignity or freedom. And the might of a religious majority must never be used to suppress those who belong to religious minority. Human rights have the greatest meaning when they protect those with less power. minorities, the vulnerables, the vulnerable communities and individuals whose beliefs may differ from those of the majority. We must therefore learn to live together with mutual respect. We do not have to agree on everything. We do not have to share the same religion, same culture, same political system or worldview, but we must respect humanity and the fundamental freedoms of one another. Mr. President, this principle is especially important when we speak about religion. Papa New Guinea, for instance, is a Christian nation believing that Jesus Christ is our Lord, Savior, and sooncoming King."},{"t":404,"topic":"Papua New Guinea constitution","text":"Christian principles profoundly have influenced our country, our communities, and our institutions. But let me make one point clear. Our Christianity must and will never be an excuse to deny another human being the freedom of conscience. And we have embedded this the fathers of my constitution the fathers of my country's constitution in 1975 in fact uh right from the foundation of our constitution section 45 of our constitution guarantees every person freedom of conscience thought and religion and that practice [snorts] or he that person can practice his or her beliefs and religion according to his own conscience or her own conscience. Our constitution also protects people against being compelled to part participate in religious observance and against attempts to force religion or irreligion upon another person. Mr. President, faith that is forced is no longer faith. I believe freedom is a choice, a God-given right implanted in the consents of every human beings."},{"t":473,"topic":"Religious freedom","text":"Our moral conscience comes from God. God does not compel worship. He calls worship through love allowing every person to exercise the freedom of choice he has given them. True faith therefore cannot be imposed by force, fear, law or persecution. A person must be free to believe. A person must be free to worship. A person must be free to change his or her belief. A person must be also free not to profess religion if he or her chooses. So the universal declaration of human right recognizes this principle in article 18, the right to freedom of thought, conscience and religion. Mr. President, history teaches us what happens when government or institution or majority use religion to suppress those who believe differently. Human beings have been persecuted, expelled, imprisoned, killed because of the fate. Humanity must learn from this history. A Christian majority nation must protect people of other religion."},{"t":537,"topic":"Religious freedom","text":"A Muslim majority nation must protect people of other religion. A Hindu majority nation must protect people of other religions. A Buddhist majority nation must protect people of other religions. And every society must respect the rights of those who choose not to profess a religion. The size of a majority does not diminish the rights of a minority. The United States, for instance, this country where we where we stand on where the assembly meets, expressed a principle more than two centuries ago to its first amendment which prohibits laws respecting the an establishment of religion or prohibiting the free exercise thereof. Government should neither impose faith upon its people nor prevent people from practicing their faith. Papa New Guinea supports this principle. We are proudly Christian. But the strength of our Christianity should not be demonstrated by suppressing other person's beliefs."},{"t":598,"topic":"Papua New Guinea diversity","text":"It should be demonstrated by having confidence in human to allow their own exercise of free choice or free conscience. Humanity can can be diverse in culture, religion and thought just like Papony Nigin is. Yet we must be united in respecting and differences we all have. Mr. President Papa New Guinea knows something about diversity. We have more than 800 languages and many different cultures and tradition. Yet for 51 years as an independent nation, we have remained together as one papu nigini. We have disagreements and challenges. We do not claim perfection. But our own experience demonstrates something important. Diversity does not mean division. People can speak different languages and still belong to one nation. People can come from different cultures and live but still live under one constitution. And people can worship different differently and still be neighbors, colleagues and fellow citizens."},{"t":662,"topic":"Religious freedom","text":"Mr. President, Papa Nigini therefore calls upon all member states to defend freedom of conscience, thought, religion and belief. I respectfully extend this call to every nation that calls Papa Nigini a friend. Every nation which we have bilateral partnership and every nation that seeks friendship and engagement with us. Look within your borders. Ensure that religious minorities are not persecuted, suppressed, intimidated or discriminated because they practice a religion that is different from majority. Whether a country is predominantly Christian or Muslim or Hindu or Buddhist or follows other religion religious tradition doesn't matter. The fate of the majority must never become an instrument for the persecution of minority. This message is not directed at one country or one religion or one region. It is a principle that must apply equally to all of us because human rights cannot be selected. We cannot demand respect for our own rights while denying those same rights to others."},{"t":727,"topic":"Climate change","text":"We cannot ask the world to respect our beliefs while refusing to respect the freedom of conscience of another human being. Mr. President, there is a wider principle here. Also, this ultimately is also about human dignity. If we recognize the dignity of every human being, then we must consider the cons conditions in which people live and the earth which we will leave behind for our children. The United Nations General Assembly has recognized the human right to a clean, healthy, sustainable environment. We value his freedom. What what is I beg a pardon. What value is freedom if a child has no water to drink? What values development if we destroy the environment that sustains life? And what inheritance are we leaving behind for our children if the forest disappears, our oceans become polluted and our climate becomes increasingly unstable? There is one reality that transcends transcends every political, economic and religious differences between us and that is we have one planet, one earth."},{"t":794,"topic":"Climate change","text":"There is no other known habitable planet presently within reach of humanity. You can be the most powerful capitalist or you can be the most powerful technocrat. You can reach out to the observable universe. Billions and billions of light years into the observable universe you find no planet like our planet earth. USA scientists, Russian scientists, big nations sets the world. Big industrialist sets the world. You cannot bring your population to another planet. This earth is our common home. What of our religion, nationality, political system, we breathe the same atmosphere. We share the same ocean. We depend upon the same global climate. And ultimately we said a consequence of what humanity does to this planet. Mr. President, think about the children of the world. A child born today did not create climate change. That child did not choose the wars of this generation."},{"t":856,"topic":"Papua New Guinea environment","text":"That child did not create pollution or the environmental dis destructions. Yet that child will inherit the consequence of the decisions we make today. We must therefore be custodians not only of the present but also of the future. Future generations cannot stand before this assembly today and argue for We must consider them when we make decisions about war and peace, development, energy, forest, oceans, minerals and global economy. Papigi understands this responsibility. We are custodians of great tropical forests, extraordinary biodiversity and vast ocean space. For us, environment is not an abstract for international discussion. It is where we live. It is where we grow our food. It is where we fish. It is The inheritance we will pass on to our children. Mr. President, in our interconnected world, decence made in one country can affect people thousands of kilometers away."},{"t":920,"topic":"Global interdependence","text":"Greenhouse gas do not recognize nestle borders. Pollution carried by ocean does not stop at migration points. Wars can disrupt food, fuel, energy, trade, supply chains far from the battlefield. Economic decisions made in the world's largest economy can reach an ordinary family in a small developing country. A mother buying food can feel the consequences. A farmer buying fuel can feel the consequences. A small business facing higher transport cost can feel the consequences. And the developing countries trying to build roads, schools and hospitals can feel the consequences. This is why leadership in powerful nations carry responsibilities beyond your nestled borders. With greater power comes greater responsibility. Papa respectfully asked leaders of the world's major powers to remember the ordinary people whose lives can be affected by decisions made far away from them. When wars disrupt f food, fuel and trade, families from far from the battlefield can experience higher prices and economic uncertainty."},{"t":990,"topic":"Climate change","text":"When climate changes, communities that have contributed little to global greenhouse gas emissions can nevertheless face rising seas, extreme weather, threats to food security, and damage to life livelihoods. Mr. President, my appeal to leaders everywhere is really simple. Put human welfare aid of war. Put humanity aired of narrow geopolitical interest. Choose dialogue and peaceful settlement wherever possible. Remember ordinary families when making major economic decisions. Balance commercial interests with the welfare of people. Use technology to advance human dignity and not diminish it. Protect our planet while pursuing development. and place the interests of our children and future generations at the heart of decisions we make today. Leadership is not measured only by the power of a nation. I beg a pardon again. Leadership is not defined only by the power you possess as a leader of a powerful nation."},{"t":1054,"topic":"Pacific nation","text":"Leadership is also measured by the responsibility that comes with how you exercise that power. Papini does not claim to have all the answers. We still are developing nation. Just few years ago, we became a middle- inome earning nation. We have our own challenges. But perhaps our position as a Pacific nation allows us to remind the larger powers of a simple reality. No nation is so powerful that it can live apart from the earth. No nation is so small that its people should be forgotten when decisions affecting humanity are made. Military strength of a nation does not make the rights of another nation less &gt;&gt; The size of an economy does not make the dignity of a poorer person less important. Technological advancement does not diminish our obligation to protect human freedom. The size of a religious majority does not reduce the rights of a minority. Power in all forms must be exercised with responsibility and care."},{"t":1116,"topic":"Christian nations","text":"Mr. President in PNZ we are many tribes we are many languages we are many churches we are many cultures but we are one nation perhaps this lesson can be taught to everyone nuini puts this to the assembly you do not have to believe what I believe in for you to defend human rights of another person let governments govern for people let churches preach and preach love to each other let mosque pray faithfully let temples welcome the worshippers let people set their own conscience. Let economies serve humanity. Let technology serve humanity. Let powerful nations exercise their power responsibly. Let nations resolve their differences peacefully wherever possible. And I pause here especially all Christian nations, all Christian nations. Our Lord and Savior Jesus talks about peace and not war. Those who are pro promoting peace are sons of God. You don't promote peace, you're not sons of God. And may this be known to every Christian nations."},{"t":1178,"topic":"Religious freedom","text":"Let no state compel the human soul. Mr. President, we may have different religions. We may have different political systems. We may have different cultures and national interests. We may we may be big nations or small nations. We may be rich or poor. We may we may possess different levels of military, economic and technological power. But beneath those differences, we say something greater. We say our humanity. We say one earth. This is our home. We must protect it. We must protect each other. We must leave our children a better world than the one we are presently living in. Papa Nigini will remain proudly proudly Christian. But we will also remain committed to the freedom of conscience, thought and religion. For ultimately faith cannot be governed or commanded by government. Faith must come from the heart. God has given humanity the capacity to choose that freedom and that freedom must be respected. God has entrusted this earth to our generation for only a short time. Let us use it wisely and pass it to the next generation."},{"t":1241,"topic":"Papua New Guinea development","text":"Let us pursue peace. Let us uphold the chart of United Nations. Let us respect the rights and dignity of every human being. Let us work together big or small nations. Let us ensure that power whether military, economic, technology or reli religious is never used to suppress the rights of others. Let us protect our common home. Let us remember always the generation who will follow follow us. Mr. President and on this note I want to close by thanking United Nations and those who have stood in Papa Nigini the last 51 years of our nationhood. We have faced many challenges as a country growing but we are growing economy. We are working to make sure enabling infrastructures reaches all people. We're making to making to make sure quality education and health services covers all people. We are moving towards a cleaner green energy. We're conserving our forests and our oceans. We're strengthening our independent judic to make our judiciary stronger, robust and independent. We protecting our free market economy."},{"t":1302,"topic":"Papua New Guinea human rights","text":"We opening doors for more foreign investments to grow. But all this comes at the backdrop of giving respect to every person in our country of so much diversity. The human right is respected. And I want to ask every one of us, let's respect human rights of every citizens of this planet. That is the least we can do. I want to assure this assembly that my government is working to the best of ability to protect the rights of the 11 million people of my country, giving them a better and equal opportunity to progress their own life, the life that God has planned for the God-given homeland that I call and many 11 million of us call Papa Nigini. I want to pray in conclusion. I want to thank every one of you who have supported Papa Nigini. In close closing for those families right across the world who are facing issues in relation to climate change and natural calamities or to those who are facing issues and pain in relation to man-made crisis."},{"t":1374,"topic":"UNGA ceremony","text":"May God give you all consolation, peace and comfort. And I pray for same blessing to not just my country but every citizen of this planet. As we work to pro protect our planet, our planet must be protected. Until Jesus come, we must work to protect our planet. God bless everyone. Thank you for listening. On behalf of the assembly, I wish to thank the prime minister of the independent state of Papu Nigin."}],"compare":[{"topic":"Religious freedom","share":0.295,"mean":0.0003,"rank":1,"others":1},{"topic":"Climate Change","share":0.1491,"mean":0.0422,"rank":16,"others":77},{"topic":"UN & its reform","share":0.0977,"mean":0.2053,"rank":145,"others":170},{"topic":"International Law & Order","share":0.0543,"mean":0.0604,"rank":82,"others":102},{"topic":"Human Rights","share":0.0528,"mean":0.0084,"rank":14,"others":24},{"topic":"Latin America","share":0.0475,"mean":0.0044,"rank":12,"others":12}]};
